                                    // If W is horizontal width, Long rails are top/bottom edges (y=0 and y=H).
             {x: this.W/2, y: this.H}  // Bottom mid
        ];

        // Friction rate per second (exponential decay)
        this.frictionRate = 0.4; 
    }

    reset(ballsArray) {
        // balls is array of {x, y, vx?, vy?, cue?}. Order preserved.
        // We clone them to ensure we don't mutate external refs if not intended, but keep properties.
        this.balls = ballsArray.map((b, i) => ({
            x: b.x, 
            y: b.y, 
            vx: (b.vx !== undefined) ? b.vx : 0,
            vy: (b.vy !== undefined) ? b.vy : 0,
            cue: !!b.cue,
            potted: false,
            // Optional mass property? Default equal.
        }));

        this.draw(); // Initial draw after reset
    }

    step(dt) {
        if (!dt || dt <= 0) return;

        // --- FRICTION & MOTION ---
        for (let b of this.balls) {
            if (b.potted) continue; 

            // Damping: v = v * e^(-rate * dt)
            const damping = Math.exp(-this.frictionRate * dt);

            b.vx *= damping;
            b.vy *= damping;

            // Stop very slow movements for determinism and precision stability
            if (Math.abs(b.vx) < 0.1 && Math.abs(b.vy) < 0.1) {
                b.vx = 0; 
                b.vy = 0;
            }

            // Move position
            b.x += b.vx * dt;
            b.y += b.vy * dt;
        }

        // --- POCKETS CHECK (After motion, before collisions) ---
        for (let b of this.balls) {
            if (b.potted) continue;

            let isPotted = false;
            for (let p of this.pockets) {
                const dx = b.x - p.x;
                const dy = b.y - p.y;
                // Using squared distance to avoid sqrt cost, but need square root radius.
                if (dx*dx + dy*dy < 900) { // Pocket Radius ~25 -> sq=625? No, let's use R_pocket=28 => sq=784. 
                    isPotted = true; break;
                }
            }

            if (isPotted) {
                b.potted = true;
                b.vx = 0; // Stop moving once potted to prevent rolling out or colliding later
                b.vy = 0;

                // Optional: Move ball slightly into pocket visual center? 
                // For physics, just mark as static. Position stays at last position (likely near edge).
            }
        }

        // --- WALL COLLISIONS ---
        for (let b of this.balls) {
            if (b.potted) continue;

            let bounced = false;

            // Left/Right Walls
            if (b.x < this.R) { 
                b.x = this.R; 
                b.vx *= -1; // Elastic reflection (momentum reverses). Energy conserved here. Friction handles decay elsewhere.
            } else if (b.x > this.W - this.R) { 
                b.x = this.W - this.R; 
                b.vx *= -1; 
            }

            // Top/Bottom Walls
            if (b.y < this.R) { 
                b.y = this.R; 
                b.vy *= -1; 
            } else if (b.y > this.H - this.R) { 
                b.y = this.H - this.R; 
                b.vy *= -1; 
            }
        }

        // --- BALL-BALL COLLISIONS ---
        for (let i = 0; i < this.balls.length; i++) {
            let b1 = this.balls[i];

            if (b1.potted) continue; 

            for (let j = i + 1; j < this.balls.length; j++) {
                let b2 = this.balls[j];

                if (b2.potted) continue;

                const dx = b2.x - b1.x;
                const dy = b2.y - b1.y;
                const distSq = dx*dx + dy*dy;

                // Check overlap
