                    let nx = dx / dist;
                    let ny = dy / dist;

                    // Relative velocity along normal
                    const vRelX = b2.vx - b1.vx;
                    const vRelY = b2.vy - b1.vy;
                    const velAlongNormal = (vRelX * nx + vRelY * ny);

                    // If separating, no impulse needed. Skip to avoid jittering if they are stuck together but moving away? 
                    // Actually with position correction below we push them apart regardless of velocity.

                    // Resolve Position Overlap first to prevent balls from sticking (Tunneling prevention)
                    const overlap = this.R * 2 - dist;
                    b1.x -= nx * (overlap / 2);
                    b1.y -= ny * (overlap / 2);
                    b2.x += nx * (overlap / 2);
                    b2.y += ny * (overlap / 2);

                    // Resolve Velocity Impulse
