                        // Elastic collision with restitution factor e = 0.95 (near-elastic, energy decreases slightly per bounce).
                        const restitution = 0.9; 

                        // Momentum conservation for equal masses: impulse magnitude j along normal
                        // Formula derived from impulse-momentum theorem:
                        // j = -(1+e) * velAlongNormal / (invMass1 + invMass2) -> if mass=1, denom=2 -> j/2? Wait.
                        // For two balls of equal mass m=1: 
                        // v1_new = v1 - n*(j/m); v2_new = v2 + n*(j/m). (Direction depends on sign conventions)
                        // Standard formula for impulse magnitude scalar J applied to b1 in direction n:
                        const j = -(1 + restitution) * velAlongNormal / 2.0;

                        const ix = nx * j;
                        const iy = ny * j;

                        b1.vx += ix; 
                        b1.vy += iy; 

                        b2.vx -= ix; // Equal mass opposite impulse on other ball? Wait signs:
                        // If n points from 1 to 2. 
                        // Force on 1 is +J*n (pushing away). Force on 2 is -J*n.
                        // Let's use simpler standard resolution logic:
