                           v_rel = v2 - v1;
                           J = -(1+e) * (v_rel · n) / (invMass1 + invMass2);
                           b1.v += J * n / m1; 
                           b2.v -= J * n / m2; // Because we want to add impulse in direction of separation?
                        */

                        // Let's stick to: Impulse acts on both balls along the normal vector.
                        // Since masses are equal, they exchange momentum equally opposite relative to center-of-mass frame.
                        b1.vx -= ix; 
                        b1.vy -= iy; 
                    } else {
                         // Even if moving apart, we already fixed position overlap above. No impulse needed.
                    }
                }
            }
        }

        this.draw();
    }

