        return this.balls.map(b => ({
            x: b.x, 
            y: b.y, 
            vx: b.vx, 
            vy: b.vy, 
            potted: b.potted, 
            cue: b.cue
        }));
    }

    shoot(vx, vy) {
        // Find cue ball and apply velocity.
        for (let b of this.balls) {
            if (b.cue && !b.potted) {
                b.vx = vx; 
                b.vy = vy;
            }
        }
    }

    pause() { /* Internal loop handles state */ }

    resume() { /* Internal loop handles state */ }

    // --- VISUALIZATION (Called by step or Game Loop) ---
    draw() {
        const canvas = document.getElementById('simCanvas');
        if (!canvas) return;

        // Set canvas size to match W, H (playfield area). 
        // We'll render rails around it using CSS on container.
        canvas.width = this.W;
        canvas.height = this.H;

        const ctx = canvas.getContext('2d');

        // Clear background (Felt color)
        ctx.fillStyle = '#2d6a4f'; 
        ctx.fillRect(0, 0, this.W, this.H);

        // Draw Pockets
        for(let p of this.pockets) {
            ctx.beginPath();
            ctx.arc(p.x, p.y, 25, 0, Math.PI * 2);
            ctx.fillStyle = '#1a1a1a';
            ctx.fill();
        }

        // Draw Balls
        for(let b of this.balls) {
            if (b.potted) continue; // Don't draw potted balls

            const x = Math.floor(b.x + 0.5); // Round to pixel center for crispness
            const y = Math.floor(b.y + 0.5);

            ctx.beginPath();
            ctx.arc(x, y, this.R, 0, Math.PI * 2);

            if (b.cue) {
