            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            ctx.fill();

            // Ball outline
            ctx.strokeStyle = '#1a1a1a';
            ctx.lineWidth = 1;
            ctx.stroke();
        }
    }
}

